import * as THREE from 'three';
import { createScene } from '../data/object.js';
import * as fs from 'fs';
import * as path from 'path';

function exportToObj(root, outputPath) {
  let vertices = [];
  let normals = [];
  let faces = [];
  let currentVertexOffset = 0;

  // Recursive function to traverse the scene graph
  function traverseAndExport(node) {
    if (node.isMesh) {
      const geometry = node.geometry;
      const position = node.position;
      const quaternion = node.quaternion;
      const scale = node.scale;

      // Get world matrix
      const matrix = new THREE.Matrix4();
      matrix.compose(position, quaternion, scale);

      // Apply parent transformations recursively
      const worldMatrix = new THREE.Matrix4();
      node.updateWorldMatrix(true, false);
      const parentWorldMatrix = node.parent ? node.parent.matrixWorld : new THREE.Matrix4();

      // Get geometry attributes
      const positionAttribute = geometry.getAttribute('position');
      const normalAttribute = geometry.getAttribute('normal');

      if (positionAttribute) {
        const vertexOffset = vertices.length;

        // Process vertices
        for (let i = 0; i < positionAttribute.count; i++) {
          const x = positionAttribute.getX(i);
          const y = positionAttribute.getY(i);
          const z = positionAttribute.getZ(i);

          const localVertex = new THREE.Vector3(x, y, z);
          localVertex.applyMatrix4(parentWorldMatrix);

          // Apply Blender Z-up conversion: -90 degrees around X-axis
          // This converts Three.js Y-up to Blender Z-up
          const rotationMatrix = new THREE.Matrix4().makeRotationX(-Math.PI / 2);
          localVertex.applyMatrix4(rotationMatrix);

          vertices.push(`v ${localVertex.x.toFixed(6)} ${localVertex.y.toFixed(6)} ${localVertex.z.toFixed(6)}`);
        }

        // Process normals
        if (normalAttribute) {
          for (let i = 0; i < normalAttribute.count; i++) {
            const x = normalAttribute.getX(i);
            const y = normalAttribute.getY(i);
            const z = normalAttribute.getZ(i);

            const localNormal = new THREE.Vector3(x, y, z);
            // Only apply rotation to normal (no translation)
            const rotationMatrix = new THREE.Matrix4().makeRotationX(-Math.PI / 2);
            localNormal.applyMatrix4(rotationMatrix);
            localNormal.normalize();

            normals.push(`vn ${localNormal.x.toFixed(6)} ${localNormal.y.toFixed(6)} ${localNormal.z.toFixed(6)}`);
          }
        } else {
          // Compute flat normals if not provided
          for (let i = 0; i < positionAttribute.count; i += 3) {
            const v1 = new THREE.Vector3(positionAttribute.getX(i), positionAttribute.getY(i), positionAttribute.getZ(i));
            const v2 = new THREE.Vector3(positionAttribute.getX(i + 1), positionAttribute.getY(i + 1), positionAttribute.getZ(i + 1));
            const v3 = new THREE.Vector3(positionAttribute.getX(i + 2), positionAttribute.getY(i + 2), positionAttribute.getZ(i + 2));

            v1.applyMatrix4(parentWorldMatrix);
            v2.applyMatrix4(parentWorldMatrix);
            v3.applyMatrix4(parentWorldMatrix);

            const edge1 = new THREE.Vector3().subVectors(v2, v1);
            const edge2 = new THREE.Vector3().subVectors(v3, v1);
            const normal = new THREE.Vector3().crossVectors(edge1, edge2).normalize();

            // Apply Z-up rotation
            const rotationMatrix = new THREE.Matrix4().makeRotationX(-Math.PI / 2);
            normal.applyMatrix4(rotationMatrix);
            normal.normalize();

            for (let j = 0; j < 3; j++) {
              normals.push(`vn ${normal.x.toFixed(6)} ${normal.y.toFixed(6)} ${normal.z.toFixed(6)}`);
            }
          }
        }

        // Process indices (triangles)
        if (geometry.index) {
          const index = geometry.index;
          for (let i = 0; i < index.count; i += 3) {
            const a = vertexOffset + index.getX(i) + 1;
            const b = vertexOffset + index.getX(i + 1) + 1;
            const c = vertexOffset + index.getX(i + 2) + 1;
            faces.push(`f ${a}//${a} ${b}//${b} ${c}//${c}`);
          }
        } else {
          // Non-indexed geometry
          for (let i = 0; i < positionAttribute.count; i += 3) {
            const a = vertexOffset + i + 1;
            const b = vertexOffset + i + 2;
            const c = vertexOffset + i + 3;
            faces.push(`f ${a}//${a} ${b}//${b} ${c}//${c}`);
          }
        }
      }
    }

    // Recursively traverse children
    if (node.children) {
      for (const child of node.children) {
        traverseAndExport(child);
      }
    }
  }

  // Start traversal
  traverseAndExport(root);

  // Write OBJ file
  let objContent = '# Exported from Three.js\n';
  objContent += '# Blender Z-up conversion: -90 degrees X-rotation applied\n\n';

  // Add group info as comment
  objContent += `o ${root.name || 'Scene'}\n`;

  for (const v of vertices) {
    objContent += v + '\n';
  }
  objContent += '\n';

  for (const n of normals) {
    objContent += n + '\n';
  }
  objContent += '\n';

  for (const f of faces) {
    objContent += f + '\n';
  }

  fs.writeFileSync(outputPath, objContent);
  console.log(`Exported to ${outputPath}`);
  console.log(`Vertices: ${vertices.length}, Normals: ${normals.length}, Faces: ${faces.length}`);
}

// Main execution
const scene = createScene();
const outputPath = '/root/output/object.obj';
exportToObj(scene, outputPath);

